.tablewrap{overflow:auto;max-height:650px}table{width:100%;border-collapse:collapse;min-width:900px;font-size:11px}th{position:sticky;top:0;background:#101b2e;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.08em;text-align:left;padding:10px;border-bottom:1px solid var(--line);z-index:2}td{padding:10px;border-bottom:1px solid #1b2a41;vertical-align:top}tr:hover td{background:#54a8ff0b}.num{text-align:right;font-variant-numeric:tabular-nums}.good{color:var(--green)}.bad{color:var(--red)}.warn{color:var(--yellow)}.muted{color:var(--muted)}.name{font-weight:800}.small{font-size:9px;color:var(--muted);margin-top:3px}.progress{height:7px;background:#152238;border-radius:99px;overflow:hidden;min-width:90px}.progress i{display:block;height:100%;background:linear-gradient(90deg,var(--purple),var(--cyan))}.summary-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:11px}.log{height:630px;overflow:auto;padding:8px 10px;background:#050a12;font:10px/1.45 Consolas,monospace}.logline{display:grid;grid-template-columns:62px 64px 1fr;gap:7px;border-bottom:1px dashed #1a2639;padding:4px 0}.level{font-weight:800}.level.HATA{color:var(--red)}.level.UYARI{color:var(--yellow)}.level.BASARILI{color:var(--green)}.level.TICK{color:var(--purple)}.level.BILGI{color:var(--cyan)}.chart{height:270px;padding:10px}canvas{width:100%;height:100%;display:block}.empty{padding:24px;text-align:center;color:var(--muted)}.two{grid-template-columns:1fr 1fr}.footer{text-align:center;color:var(--muted);font-size:9px;padding:13px}
