<section id="overview" class="page active"><div class="grid market-layout"><div class="stack"><section class="card"><div class="head"><div><div class="title">ŞİRKET DEĞER LİSTESİ</div><div class="section-note">Şirket değeri, hisse tahmini, finans, kalite ve ürün ekosistemi</div></div><div id="updated" class="section-note">—</div></div><div id="companies" class="company-grid"></div></section><section class="card"><div class="head"><div><div class="title">ŞİRKET DEĞERİ VE KASA GRAFİĞİ</div><div class="section-note">Tarayıcı açık kaldığı sürece son 120 örnek</div></div></div><div class="chart"><canvas id="chart"></canvas></div></section></div><aside class="stack"><section class="card"><div class="head"><div class="title">SON TICK</div></div><div id="tickSummary" class="summary-grid"></div></section><section class="card"><div class="head"><div class="title">EN DEĞERLİ UYGULAMALAR</div></div><div id="topApps" class="tablewrap"></div></section></aside></div></section>

