</div>
<script>
const S={history:new Map(),data:null};const money=new Intl.NumberFormat("tr-TR",{style:"currency",currency:"TRY",maximumFractionDigits:2});const num=new Intl.NumberFormat("tr-TR",{maximumFractionDigits:2});const integer=new Intl.NumberFormat("tr-TR",{maximumFractionDigits:0});const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));const pct=v=>`${num.format(Number(v||0))}%`;const m=v=>money.format(Number(v||0));const n=v=>num.format(Number(v||0));const i=v=>integer.format(Number(v||0));const bool=v=>v===true;const text=(id,v)=>document.getElementById(id).textContent=v;const color=index=>["#39e5a4","#59a8ff","#b78dff","#ffd166","#42d5ef","#ff6678"][index%6];
function metric(label,value,cls=""){return `<div class="metric"><span>${esc(label)}</span><b class="${cls}">${esc(value)}</b></div>`}function bar(label,value){const v=Math.max(0,Math.min(100,Number(value||0)));return `<div class="barrow"><span>${esc(label)}</span><div class="bar"><i style="width:${v}%"></i></div><b>${n(v)}</b></div>`}function chip(v,cls=""){return `<span class="chip ${cls}">${esc(v)}</span>`}function appProduct(a){return a?.urun||null}function isActiveProduct(a){const u=appProduct(a);return bool(a?.piyasada)&&u&&bool(u.aktif)}
function render(data){S.data=data;const g=data.genel||{},p=data.piyasa||{},o=p.islemeOzeti||{};text("motor",data.motor?.motorKimligi||"—");text("tick",data.motor?.tickNumarasi??0);text("version",data.motor?.borsaSurumu||"—");text("updated",new Date(data.motor?.sunucuZamani||Date.now()).toLocaleString("tr-TR"));text("totalValue",m(g.toplamSirketDegeri));text("valueNote",`${i(g.toplamSirketSayisi)} şirket · ${i(g.teknikUygulamaSayisi)} teknik uygulama`);text("totalCash",m(g.toplamSirketKasasi));text("incomeNote",`${m(g.toplamNetGelir)} toplam net gelir`);text("totalDebt",m(g.toplamBorc));text("debtNote",`${i((data.krediPiyasasi||[]).filter(x=>x.kredi?.aktif).length)} aktif kredi`);text("totalSubs",i(g.toplamAbone));text("subNote",`${i(g.aktifMusteriSayisi)} aktif pazar müşterisi`);text("appCount",`${i(g.piyasadakiUygulamaSayisi)} / ${i(g.teknikUygulamaSayisi)}`);text("protocolCount",`${i(g.piyasadakiProtokolSayisi)} / ${i(g.teknikProtokolSayisi)}`);text("connected",`${i(g.bagliSirketSayisi)} / ${i(g.toplamSirketSayisi)}`);text("serviceNote",`${i(g.toplamHizmetIlani)} toplam hizmet ilanı`);text("attackCount",`${i(g.toplamEngellenenSaldiri)} / ${i(g.toplamBasariliSaldiri)}`);text("lossNote",`${m(g.toplamGuvenlikKaybi)} güvenlik kaybı`);renderCompanies(data.sirketler||[]);renderApps(data.uygulamaPiyasasi||[]);renderProtocols(data.protokolPiyasasi||[]);renderServices(data.hizmetPiyasasi||[]);renderFinance(data.sirketler||[]);renderCredits(data.krediPiyasasi||[]);renderContracts(data.sozlesmePiyasasi||[]);renderInvestments(data.yatirimPiyasasi||[]);renderSecurity(data.sirketler||[]);renderSummary(o);renderLogs(data.olaylar||[]);updateHistory(data.sirketler||[]);drawChart();renderTopApps(data.uygulamaPiyasasi||[])}
function renderCompanies(list){const el=document.getElementById("companies");const sorted=[...list].sort((a,b)=>Number(b.isletim?.sirketDegeri||0)-Number(a.isletim?.sirketDegeri||0));if(!sorted.length){el.innerHTML='<div class="empty">Şirket bulunamadı.</div>';return}el.innerHTML=sorted.map((c,index)=>{const op=c.isletim||{},apps=(c.kodTabanliYayinlar?.uygulamalar||[]),protocols=(c.kodTabanliYayinlar?.protokoller||[]),invest=Object.entries(op.yatirimSeviyeleri||{}).filter(([,v])=>Number(v)>0);return `<article class="company" style="--c:${color(index)}"><div class="company-top"><div><div class="company-name">${esc(c.sirketAdi)}</div><div class="company-id">${esc(c.sirketKimligi)} · ${esc(c.sunucuAdresi)}:${esc(c.sunucuPortu)} · v${esc(c.sunucuSurumu||"—")}</div><span class="state ${c.bagli?"":"off"}">${c.bagli?"BAĞLI":"ÇEVRİMDIŞI"}</span></div><div class="rank">#${index+1}</div></div><div class="metrics">${metric("Şirket değeri",m(op.sirketDegeri),"good")}${metric("Hisse tahmini",m(op.tahminiHisseFiyati))}${metric("Kasa",m(c.kasa),"good")}${metric("Borç",m(op.toplamBorc),Number(op.toplamBorc)>0?"warn":"")}${metric("Abone",i(op.toplamAboneSayisi))}${metric("Kredi notu",i(op.krediNotu))}${metric("Uygulama",`${apps.filter(x=>x.piyasada).length}/${apps.length}`)}${metric("Protokol",`${protocols.filter(x=>x.piyasada).length}/${protocols.length}`)}${metric("Gecikme",`${n(c.sonGecikmeMs)} ms`)}</div><div class="bars">${bar("Kod",c.kodKalitesiPuani)}${bar("Performans",c.performansPuani)}${bar("Güvenlik",c.guvenlikPuani)}${bar("İtibar",c.itibarPuani)}${bar("Güvenilir",c.guvenilirlikPuani)}${bar("Memnuniyet",c.ortalamaMusteriMemnuniyeti)}</div><div class="chips">${apps.map(x=>chip(`${x.uygulama?.uygulamaAdi||x.uygulama?.uygulamaKimligi} ${x.piyasada?"●":"○"}`,x.piyasada?"good":"")).join("")}${protocols.map(x=>chip(`${x.protokol?.protokolAdi||x.protokol?.protokolKimligi} ${x.piyasada?"●":"○"}`,x.piyasada?"good":"")).join("")}${invest.map(([k,v])=>chip(`${k} L${v}`)).join("")}</div></article>`}).join("")}
function renderApps(list){const body=document.getElementById("appsBody");if(!list.length){body.innerHTML='<tr><td colspan="13" class="empty">Kodlanmış uygulama yok.</td></tr>';return}body.innerHTML=[...list].sort((a,b)=>Number(appProduct(b)?.toplamGelir||0)-Number(appProduct(a)?.toplamGelir||0)).map(a=>{const app=a.uygulama||{},d=a.dogrulama||{},u=appProduct(a),active=isActiveProduct(a),capacity=Number(u?.kullaniciKapasitesi||0),users=Number(u?.aktifKullaniciSayisi||0),ratio=capacity?Math.min(100,users/capacity*100):0;return `<tr><td><div class="name">${esc(app.uygulamaAdi||app.uygulamaKimligi)}</div><div class="small">${esc(app.uygulamaKimligi)} · v${esc(app.surum||"—")} · ${(app.ozellikler||[]).length} özellik</div></td><td>${esc(a.sirketAdi)}</td><td>${esc(app.kategori||"—")}</td><td class="${d.gecerli?"good":"bad"}">${d.gecerli?"STANDARDI GEÇTİ":"EKSİK"}<div class="small">${esc(d.durum||"")}</div></td><td class="${active?"good":a.piyasada?"warn":"muted"}">${active?"YAYINDA":a.piyasada?"DURDURULDU":"8090 BEKLİYOR"}</td><td>${esc(u?.fiyatlandirmaModeli||"—")}</td><td class="num">${u?m(u.abonelikUcreti):"—"}</td><td class="num">${u?m(u.kullanimBasinaUcret):"—"}</td><td><div>${i(users)} / ${i(capacity)}</div><div class="progress"><i style="width:${ratio}%"></i></div></td><td class="num">${u?n(u.urunKalitesi):"—"}</td><td class="num">${u?n(u.urunMemnuniyeti):"—"}</td><td class="num good">${u?m(u.toplamGelir):"—"}</td><td>${(app.desteklenenProtokoller||[]).map(x=>chip(x)).join("")||"—"}</td></tr>`}).join("")}
function renderTopApps(list){const active=list.filter(x=>x.urun).sort((a,b)=>Number(b.urun?.aktifKullaniciSayisi||0)-Number(a.urun?.aktifKullaniciSayisi||0)).slice(0,8);const el=document.getElementById("topApps");el.innerHTML=active.length?`<table><thead><tr><th>Uygulama</th><th>Şirket</th><th class="num">Abone</th><th class="num">Gelir</th></tr></thead><tbody>${active.map(x=>`<tr><td>${esc(x.uygulama?.uygulamaAdi)}</td><td>${esc(x.sirketAdi)}</td><td class="num">${i(x.urun?.aktifKullaniciSayisi)}</td><td class="num good">${m(x.urun?.toplamGelir)}</td></tr>`).join("")}</tbody></table>`:'<div class="empty">Henüz ticari uygulama yayını yok.</div>'}
function renderProtocols(list){const body=document.getElementById("protocolsBody");if(!list.length){body.innerHTML='<tr><td colspan="9" class="empty">Özel protokol yok.</td></tr>';return}body.innerHTML=list.map(x=>{const p=x.teknikProtokol||{};return `<tr><td><div class="name">${esc(p.protokolAdi||p.protokolKimligi)}</div><div class="small">${esc(p.protokolKimligi)}</div></td><td>${esc(x.sirketAdi)}</td><td>${esc(p.surum||"—")}</td><td><div>${esc(p.semaKimligi||"—")}</div><div class="small">${esc(p.semaOzeti||"")}</div></td><td class="${x.gecerli?"good":"bad"}">${x.gecerli?"GEÇERLİ":"EKSİK"}</td><td class="${x.piyasada?"good":"muted"}">${x.piyasada?"LİSANSLANABİLİR":"8090 BEKLİYOR"}</td><td>${(p.yetkinlikler||[]).map(y=>chip(`${y.yetkinlikKimligi} → ${y.hizmetKimligi}`)).join("")}</td><td>${(p.uyumluProtokoller||[]).map(y=>chip(y)).join("")||"—"}</td><td>${esc(x.piyasaProtokolKimligi||"—")}</td></tr>`}).join("")}
function renderServices(list){const body=document.getElementById("servicesBody");if(!list.length){body.innerHTML='<tr><td colspan="10" class="empty">Hizmet yok.</td></tr>';return}body.innerHTML=list.map(s=>`<tr><td><div class="name">${esc(s.hizmetKimligi)}</div><div class="small">v${esc(s.hizmetSurumu)} · ${esc(s.aciklama||"")}</div></td><td class="${s.aktif?"good":"bad"}">${s.aktif?"AKTİF":"KAPALI"}</td><td class="num">${i(s.talepSayisi)}</td><td class="num ${Number(s.kotuNiyetliTalepSayisi)>0?"bad":""}">${i(s.kotuNiyetliTalepSayisi)}</td><td class="num">${n(s.ortalamaZorlukSeviyesi)}</td><td class="num">${m(s.toplamTalepButcesi)}</td><td class="num good">${s.enUcuzFiyat==null?"—":m(s.enUcuzFiyat)}</td><td class="num">${s.enPahaliFiyat==null?"—":m(s.enPahaliFiyat)}</td><td class="num">${i(s.saglayiciSayisi)}</td><td>${(s.saglayicilar||[]).map(x=>chip(`${x.sirketAdi} ${m(x.birimFiyat)} · K${n(x.kodKalitesiPuani)} P${n(x.performansPuani)} G${n(x.guvenlikPuani)}`,x.bagli?"good":"bad")).join("")||'<span class="bad">Sağlayıcı yok</span>'}</td></tr>`).join("")}
function renderFinance(list){const body=document.getElementById("financeBody");body.innerHTML=[...list].sort((a,b)=>Number(b.isletim?.sirketDegeri||0)-Number(a.isletim?.sirketDegeri||0)).map(c=>{const o=c.isletim||{};return `<tr><td class="name">${esc(c.sirketAdi)}</td><td class="num good">${m(o.sirketDegeri)}</td><td class="num">${m(o.tahminiHisseFiyati)}</td><td class="num">${m(c.kasa)}</td><td class="num ${Number(o.toplamBorc)>0?"warn":""}">${m(o.toplamBorc)}</td><td class="num">${i(o.krediNotu)}</td><td class="num good">${m(o.toplamAbonelikGeliri)}</td><td class="num good">${m(o.toplamUrunGeliri)}</td><td class="num bad">${m(o.toplamIsletmeGideri)}</td><td class="num bad">${m(o.toplamFinansmanGideri)}</td></tr>`}).join("")}
function renderCredits(list){const body=document.getElementById("creditsBody");const credits=list.filter(x=>x.kredi);body.innerHTML=credits.length?credits.map(x=>{const k=x.kredi;return `<tr><td>${esc(x.sirketAdi)}</td><td>${esc(k.krediTuru)}</td><td class="num">${m(k.anaPara)}</td><td class="num warn">${m(k.kalanBorc)}</td><td class="num">${m(k.taksitTutari)}</td><td class="num">${i(k.kalanTaksit)}</td><td class="num">${pct(Number(k.tickFaizOrani||0)*100)}</td><td class="num ${Number(k.gecikmeSayisi)>0?"bad":""}">${i(k.gecikmeSayisi)}</td><td class="${k.aktif?"warn":"good"}">${k.aktif?"AKTİF":"KAPANDI"}</td></tr>`}).join(""):'<tr><td colspan="9" class="empty">Kredi kaydı yok.</td></tr>'}
function renderContracts(list){const body=document.getElementById("contractsBody");body.innerHTML=list.length?list.map(x=>{const s=x.sozlesme;return `<tr><td>${esc(x.sirketAdi)}</td><td><div class="name">${esc(s.baslik)}</div><div class="small">${esc(s.sozlesmeKimligi)}</div></td><td>${esc(s.kategori)}</td><td>${i(s.baslangicTicki)}–${i(s.bitisTicki)}</td><td class="num good">${m(s.tickOdemesi)}</td><td class="num bad">${m(s.ihlalCezasi)}</td><td class="num">${i(s.basariliTickSayisi)}</td><td class="num ${Number(s.ihlalSayisi)>0?"bad":""}">${i(s.ihlalSayisi)}</td><td class="${s.aktif?"good":"muted"}">${s.aktif?"AKTİF":"BİTTİ"}</td></tr>`}).join(""):'<tr><td colspan="9" class="empty">Aktif veya geçmiş SLA yok.</td></tr>'}
function renderInvestments(list){const body=document.getElementById("investmentsBody");const active=list.filter(x=>Number(x.seviye)>0).sort((a,b)=>a.sirketAdi.localeCompare(b.sirketAdi,"tr")||Number(b.seviye)-Number(a.seviye));body.innerHTML=active.length?active.map(x=>`<tr><td>${esc(x.sirketAdi)}</td><td>${esc(x.yatirimTuru)}</td><td class="num good">${i(x.seviye)}</td></tr>`).join(""):'<tr><td colspan="3" class="empty">Henüz yatırım yapılmadı.</td></tr>'}
function renderSecurity(list){const body=document.getElementById("securityBody");body.innerHTML=[...list].sort((a,b)=>Number(b.guvenlikPuani)-Number(a.guvenlikPuani)).map(c=>{const risk=Number(c.guvenlikPuani)>=80?"DÜŞÜK":Number(c.guvenlikPuani)>=55?"ORTA":"YÜKSEK";return `<tr><td class="name">${esc(c.sirketAdi)}</td><td class="num ${risk==="DÜŞÜK"?"good":risk==="YÜKSEK"?"bad":"warn"}">${n(c.guvenlikPuani)}</td><td class="num">${n(c.kodKalitesiPuani)}</td><td class="num good">${i(c.engellenenSaldiriSayisi)}</td><td class="num ${Number(c.basariliSaldiriSayisi)>0?"bad":""}">${i(c.basariliSaldiriSayisi)}</td><td class="num bad">${m(c.toplamGuvenlikKaybi)}</td><td class="${risk==="DÜŞÜK"?"good":risk==="YÜKSEK"?"bad":"warn"}">${risk}</td></tr>`}).join("")}
function renderSummary(o){document.getElementById("tickSummary").innerHTML=[metric("Talep",i(o.toplamTalepSayisi)),metric("Başarılı",i(o.basariliIsSayisi),"good"),metric("Başarısız",i(o.basarisizIsSayisi),Number(o.basarisizIsSayisi)>0?"bad":""),metric("Şüpheli",i(o.kotuNiyetliIsSayisi),Number(o.kotuNiyetliIsSayisi)>0?"warn":""),metric("Engellenen",i(o.engellenenSaldiriSayisi),"good"),metric("Saldırı başarılı",i(o.basariliSaldiriSayisi),Number(o.basariliSaldiriSayisi)>0?"bad":""),metric("Ciro",m(o.toplamCiro),"good"),metric("Başarı",pct(o.basariOrani)),metric("Zaman aşımı",i(o.zamanAsimiSayisi),Number(o.zamanAsimiSayisi)>0?"bad":"")].join("")}
function renderLogs(list){const el=document.getElementById("logs"),near=el.scrollHeight-el.scrollTop-el.clientHeight<80;el.innerHTML=list.map(x=>`<div class="logline"><span class="muted">${new Date(x.zaman).toLocaleTimeString("tr-TR")}</span><span class="level ${esc(x.seviye)}">${esc(x.seviye)}</span><span>${esc(x.mesaj)}</span></div>`).join("")||'<div class="empty">Motor olayı yok.</div>';if(near)el.scrollTop=el.scrollHeight}
function updateHistory(list){const now=Date.now();list.forEach(c=>{if(!S.history.has(c.sirketKimligi))S.history.set(c.sirketKimligi,{name:c.sirketAdi,value:[],cash:[]});const h=S.history.get(c.sirketKimligi);h.name=c.sirketAdi;h.value.push({x:now,y:Number(c.isletim?.sirketDegeri||0)});h.cash.push({x:now,y:Number(c.kasa||0)});if(h.value.length>120)h.value.shift();if(h.cash.length>120)h.cash.shift()})}
function drawChart(){const canvas=document.getElementById("chart"),rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.max(1,rect.width*dpr);canvas.height=Math.max(1,rect.height*dpr);const ctx=canvas.getContext("2d");ctx.scale(dpr,dpr);const w=rect.width,h=rect.height,p={l:58,r:16,t:15,b:34};ctx.clearRect(0,0,w,h);const series=[...S.history.values()].filter(x=>x.value.length);const values=series.flatMap(x=>x.value.map(y=>y.y));let min=Math.min(0,...values),max=Math.max(1,...values);if(min===max)max=min+1;ctx.strokeStyle="#20304a";ctx.fillStyle="#8093af";ctx.font="9px Segoe UI";for(let k=0;k<=4;k++){const y=p.t+(h-p.t-p.b)*k/4;ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(w-p.r,y);ctx.stroke();ctx.fillText(n(max-(max-min)*k/4),3,y+3)}series.forEach((s,index)=>{ctx.strokeStyle=color(index);ctx.lineWidth=2;ctx.beginPath();s.value.forEach((pt,j)=>{const x=p.l+(w-p.l-p.r)*(s.value.length<=1?0:j/(s.value.length-1)),y=p.t+(h-p.t-p.b)*(1-(pt.y-min)/(max-min));j?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle=color(index);ctx.fillRect(p.l+index*140,h-17,10,3);ctx.fillStyle="#bdcbe0";ctx.fillText(s.name,p.l+14+index*140,h-13)})}
async function refresh(){try{const r=await fetch(`/api/durum?t=${Date.now()}`,{cache:"no-store"});if(!r.ok)throw new Error(`HTTP ${r.status}`);const data=await r.json();render(data);document.getElementById("dot").className="dot ok";text("connection","CANLI")}catch(error){document.getElementById("dot").className="dot bad";text("connection","BAĞLANTI YOK");console.error(error)}}
document.querySelectorAll(".tab").forEach(button=>button.addEventListener("click",()=>{document.querySelectorAll(".tab").forEach(x=>x.classList.remove("active"));document.querySelectorAll(".page").forEach(x=>x.classList.remove("active"));button.classList.add("active");document.getElementById(button.dataset.page).classList.add("active");drawChart()}));setInterval(()=>text("clock",new Date().toLocaleTimeString("tr-TR")),250);setInterval(refresh,1000);window.addEventListener("resize",drawChart);refresh();
</script>
</body>
</html>
""";
}
